css:
.tiles {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.tile {
  display: grid;
  place-items: center;
  height: 72px;
  border: 1px solid #fdba74;
  border-radius: 8px;
  background-color: #fff7ed;
  font-weight: 600;
}

.pointer {
  cursor: pointer;
}

.grab {
  cursor: grab;
}

.help {
  cursor: help;
}

.text {
  cursor: text;
}

.move {
  cursor: move;
}

.blocked {
  border-color: #d4d4d8;
  background-image: repeating-linear-gradient(45deg, #f4f4f5 0 8px, #e4e4e7 8px 16px);
  color: #71717a;
  cursor: not-allowed;
}
